```javascript
import { Group, Mesh, BoxGeometry, PlaneGeometry, MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const {
    ink = '#16161d',
    paper = '#e8ecf2',
    accent = '#ff2a38',
    surface = '#0b0b10',
  } = config.intent?.visualSpec?.colors || {};

  const imageUrl = config.imageUrl;
  const pos = config.scenePosition || { x: 1.25, y: 1.6, z: 0 };
  const rot = config.sceneRotation || { x: 0, y: 0, z: 0 };
  const sc = config.sceneScale || { x: 1, y: 1, z: 1 };
  const primitivesToApply = config.cinematicPrimitives || [];
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];

  const group = new Group();
  group.position.set(pos.x, pos.y, pos.z);
  group.rotation.set(rot.x, rot.y, rot.z);
  group.scale.set(sc.x, sc.y, sc.y);

  // --- Card Dimensions ---
  const cardW = 2.0;
  const cardH = 1.4;
  const cardD = 0.05;

  // --- Shadow ---
  const shadowMat = new MeshBasicNodeMaterial({
    color: 0x000000,
    transparent: true,
    opacity: 0.5,
    depthWrite: false,
  });
  const shadowGeo = new PlaneGeometry(cardW + 0.12, cardH + 0.12);
  const shadow = new Mesh(shadowGeo, shadowMat);
  shadow.position.z = -0.08;
  shadow.position.y = -0.06;
  shadow.name = 'shadow';
  group.add(shadow);

  // --- Card Body (extruded box for depth) ---
  const frontMat = new MeshBasicNodeMaterial({
    color: surface,
    transparent: true,
    opacity: 0.95,
    roughness: 0.6,
    metalness: 0.3,
  });
  const sideMat = new MeshBasicNodeMaterial({
    color: ink,
  });
  const cardMatArray = [sideMat, sideMat, sideMat, sideMat, frontMat, frontMat];
  const cardGeo = new BoxGeometry(cardW, cardH, cardD);
  const card = new Mesh(cardGeo, cardMatArray);
  card.name = 'card-bg';
  group.add(card);

  // --- Load Texture onto Front Face ---
  if (imageUrl) {
    ctx.textureLoader.loadTexture(imageUrl).then((tex) => {
      frontMat.map = tex;
      frontMat.needsUpdate = true;
    });
  }

  // --- Accent Edge (top edge of the card) ---
  const edgeMat = new MeshBasicNodeMaterial({ color: accent });
  const edgeGeo = new BoxGeometry(cardW, 0.03, 0.04);
  const edge = new Mesh(edgeGeo, edgeMat);
  edge.position.y = cardH / 2;
  edge.name = 'accent-edge';
  group.add(edge);

  // --- Text Content (rendered from spec items) ---
  const textGroup = new Group();
  textGroup.position.z = cardD / 2 + 0.01;
  textGroup.position.y = 0.1;

  if (textItems.length > 0) {
    textItems.forEach((item, index) => {
      const fontSize = item.typography?.fontSize || 0.13;
      const textObj = ctx.fontAtlas.createText(item.text, {
        fontSize,
        color: paper,
        align: 'center',
        maxWidthPx: cardW * 80,
        letterSpacingPx: item.role === 'caption' ? 0.8 : 0.0,
      });
      if (textObj) {
        const yOffset = 0.3 - index * 0.28;
        textObj.position.y = yOffset;
        textGroup.add(textObj);
      }
    });
  }
  group.add(textGroup);

  // --- Interactions (Hover lift, Press click) ---
  const originalPosY = group.position.y;
  const originalScaleX = group.scale.x;
  const originalScaleY = group.scale.y;

  group.userData.handlers = {
    onPointerEnter: () => {
      gsap.to(group.position, {
        y: originalPosY + 0.15,
        duration: 0.3,
        ease: 'power2.out',
      });
      gsap.to(group.scale, {
        x: 1.04,
        y: 1.04,
        duration: 0.3,
        ease: 'power2.out',
      });
    },
    onPointerLeave: () => {
      gsap.to(group.position, {
        y: originalPosY,
        duration: 0.3,
        ease: 'power2.out',
      });
      gsap.to(group.scale, {
        x: originalScaleX,
        y: originalScaleY,
        duration: 0.3,
        ease: 'power2.out',
      });
    },
    onClick: () => {
      gsap.timeline()
        .to(group.scale, {
          x: 0.97,
          y: 0.97,
          duration: 0.12,
          ease: 'back.in(2)',
        })
        .to(group.scale, {
          x: originalScaleX,
          y: originalScaleY,
          duration: 0.5,
          ease: 'power4.out',
        });
      if (ctx.emit) ctx.emit('hub-pricing.select');
    },
  };

  // --- Apply Cinematic Primitives (parallax-scroll) ---
  const appliedPrimitives = [];
  for (const p of primitivesToApply) {
    if (ctx.primitives && ctx.primitives[p.name]) {
      const result = ctx.primitives[p.name](group, p.params);
      if (result) appliedPrimitives.push(result);
    }
  }

  // --- Cleanup ---
  group.userData.cleanup = () => {
    gsap.killTweensOf(group.position);
    gsap.killTweensOf(group.scale);
    gsap.killTweensOf(group.rotation);

    shadowMat.dispose();
    shadowGeo.dispose();

    cardMatArray.forEach((m) => m.dispose());
    cardGeo.dispose();

    edgeMat.dispose();
    edgeGeo.dispose();

    // Dispose texture if loaded
    if (frontMat.map) frontMat.map.dispose();

    // Dispose text children
    textGroup.traverse((child) => {
      if (child.isMesh) {
        child.geometry?.dispose();
        if (child.material) {
          if (Array.isArray(child.material)) {
            child.material.forEach((m) => m.dispose());
          } else {
            child.material.dispose();
          }
        }
      }
    });

    // Cleanup applied primitives
    for (const ap of appliedPrimitives) {
      if (ap.cleanup) ap.cleanup();
    }
  };

  return group;
}
